1	/**
2	 * LLM Factory - Centralized LLM instantiation for memory services
3	 *
4	 * Uses the AI provider abstraction layer (lib/ai/) to support
5	 * multiple backends (OpenAI, Gemini, etc.).
6	 *
7	 * Returns a thin wrapper with the same `.invoke()` contract that
8	 * all memory consumers expect, so no caller changes needed.
9	 */
10	
11	import { getLLMProvider } from '@/lib/ai';
12	import type { ChatMessage } from '@/lib/ai';
13	
14	export type MemoryLLMRole = 'classification' | 'compression' | 'pattern' | 'zreport' | 'anonymizer';
15	
16	const ROLE_DEFAULTS: Record<MemoryLLMRole, {
17	  envKey: string;
18	  temperature: number;
19	  maxTokens?: number;
20	}> = {
21	  classification: {
22	    envKey: 'MEMORY_CLASSIFICATION_MODEL',
23	    temperature: 0.1,
24	    maxTokens: 200,
25	  },
26	  compression: {
27	    envKey: 'MEMORY_COMPRESSION_MODEL',
28	    temperature: 0.1,
29	  },
30	  pattern: {
31	    envKey: 'MEMORY_PATTERN_MODEL',
32	    temperature: 0.1,
33	    maxTokens: 300,
34	  },
35	  zreport: {
36	    envKey: 'MEMORY_ZREPORT_MODEL',
37	    temperature: 0.2,
38	    maxTokens: 500,
39	  },
40	  anonymizer: {
41	    envKey: 'MEMORY_ANONYMIZER_MODEL',
42	    temperature: 0.1,
43	    maxTokens: 400,
44	  },
45	};
46	
47	/** Response type matching what consumers expect (compatible with extractResponseText) */
48	interface LLMResponse {
49	  content: string;
50	}
51	
52	/** Thin wrapper that exposes the `.invoke()` contract consumers expect */
53	interface MemoryLLM {
54	  invoke(messages: Array<{ role: string; content: string }>): Promise<LLMResponse>;
55	}
56	
57	/**
58	 * Create an LLM instance for the given memory role.
59	 * Returns an object with `.invoke()` that delegates to the provider abstraction.
60	 *
61	 * Optional `overrides` allow callers to override role defaults (e.g. maxTokens).
62	 */
63	export function createMemoryLLM(
64	  role: MemoryLLMRole,
65	  overrides?: { maxTokens?: number }
66	): MemoryLLM {
67	  const config = ROLE_DEFAULTS[role];
68	  const model = process.env[config.envKey] || undefined;
69	  const provider = getLLMProvider(model);
