1	/**
2	 * Model Router Providers
3	 *
4	 * Handles routing chat completion requests to the appropriate
5	 * AI provider (OpenAI, Anthropic, Google, xAI, DeepSeek).
6	 *
7	 * Models are loaded from the database with caching, with fallback
8	 * to hardcoded constants for safety.
9	 */
10	
11	import { eq } from 'drizzle-orm';
12	
13	import { db } from '@/db';
14	import { aiModelsTable } from '@/db/schema';
15	
16	import {
17	  ChatCompletionChunk,
18	  ChatCompletionRequest,
19	  ChatCompletionResponse,
20	  ChatMessage,
21	  MODEL_ALIASES,
22	  MODEL_PRICING,
23	  MODEL_PROVIDERS,
24	  ModelProvider,
25	} from './types';
