27	// ============================================================================
28	// Model Cache - Database-driven with TTL
29	// ============================================================================
30	
31	interface CachedModel {
32	  model_id: string;
33	  provider: ModelProvider;
34	  input_price: number;
35	  output_price: number;
36	  aliases: string[] | null;
37	}
38	
39	let modelCache: Map<string, CachedModel> | null = null;
40	let aliasCache: Map<string, string> | null = null;
41	let cacheExpiry: number = 0;
42	const CACHE_TTL_MS = 60000; // 1 minute cache
43	
44	/**
45	 * Load models from database into cache
46	 */
47	async function loadModelsFromDatabase(): Promise<void> {
48	  try {
49	    const models = await db
50	      .select({
51	        model_id: aiModelsTable.model_id,
52	        provider: aiModelsTable.provider,
53	        input_price: aiModelsTable.input_price,
54	        output_price: aiModelsTable.output_price,
55	        aliases: aiModelsTable.aliases,
56	      })
57	      .from(aiModelsTable)
58	      .where(eq(aiModelsTable.is_enabled, true));
59	
60	    modelCache = new Map();
61	    aliasCache = new Map();
62	
63	    for (const model of models) {
64	      const cachedModel: CachedModel = {
65	        model_id: model.model_id,
66	        provider: model.provider as ModelProvider,
67	        input_price: model.input_price,
68	        output_price: model.output_price,
69	        aliases: model.aliases,
70	      };
71	      modelCache.set(model.model_id, cachedModel);
72	
73	      // Build alias cache
74	      if (model.aliases) {
75	        for (const alias of model.aliases) {
76	          aliasCache.set(alias.toLowerCase(), model.model_id);
77	        }
78	      }
79	    }
80	
81	    cacheExpiry = Date.now() + CACHE_TTL_MS;
82	    console.log(`[ModelRouter] Loaded ${models.length} models from database`);
83	  } catch (error) {
84	    console.error('[ModelRouter] Failed to load models from database, using fallback:', error);
85	    // Don't set cache on error - will use fallback
86	  }
87	}
88	
89	/**
90	 * Get models from cache, refreshing if expired
91	 */
92	async function getModelCache(): Promise<Map<string, CachedModel>> {
93	  if (!modelCache || Date.now() >= cacheExpiry) {
94	    await loadModelsFromDatabase();
95	  }
96	  return modelCache || new Map();
97	}
98	
99	/**
100	 * Get alias cache, refreshing if expired
101	 */
102	async function getAliasCache(): Promise<Map<string, string>> {
103	  if (!aliasCache || Date.now() >= cacheExpiry) {
104	    await loadModelsFromDatabase();
105	  }
106	  return aliasCache || new Map();
107	}
108	
109	// ============================================================================
110	// Provider Configuration
111	// ============================================================================
112	
113	// Provider base URLs
114	const PROVIDER_URLS: Record<ModelProvider, string> = {
115	  openai: 'https://api.openai.com/v1',
116	  anthropic: 'https://api.anthropic.com/v1',
117	  google: 'https://generativelanguage.googleapis.com/v1beta',
118	  xai: 'https://api.x.ai/v1',
119	  deepseek: 'https://api.deepseek.com/v1',
120	};
121	
122	/**
123	 * Resolve model alias to actual model ID (sync version for backwards compatibility)
124	 * Checks hardcoded aliases only - for database aliases, use resolveModelAliasAsync
125	 */
126	export function resolveModelAlias(model: string): string {
127	  return MODEL_ALIASES[model.toLowerCase()] || model;
128	}
129	
130	/**
131	 * Resolve model alias to actual model ID (async version with database lookup)
132	 * Checks database aliases first, falls back to hardcoded aliases
133	 */
134	export async function resolveModelAliasAsync(model: string): Promise<string> {
135	  const lowerModel = model.toLowerCase();
136	
137	  // Check database alias cache first
138	  const aliases = await getAliasCache();
139	  if (aliases.has(lowerModel)) {
140	    return aliases.get(lowerModel)!;
141	  }
142	
143	  // Check database model IDs directly
144	  const models = await getModelCache();
145	  if (models.has(model)) {
146	    return model;
147	  }
148	
149	  // Fall back to hardcoded aliases
150	  return MODEL_ALIASES[lowerModel] || model;
151	}
152	
153	/**
154	 * Get provider for a model (sync version for backwards compatibility)
155	 */
156	export function getProviderForModel(model: string): ModelProvider {
157	  const resolvedModel = resolveModelAlias(model);
158	  const provider = MODEL_PROVIDERS[resolvedModel];
159	
160	  if (!provider) {
161	    // Try to infer from model name
162	    if (resolvedModel.startsWith('gpt-') || resolvedModel.startsWith('o1')) {
163	      return 'openai';
164	    }
165	    if (resolvedModel.startsWith('claude')) {
166	      return 'anthropic';
167	    }
168	    if (resolvedModel.startsWith('gemini')) {
169	      return 'google';
170	    }
171	    if (resolvedModel.startsWith('grok')) {
172	      return 'xai';
173	    }
174	    if (resolvedModel.startsWith('deepseek')) {
175	      return 'deepseek';
176	    }
177	    throw new Error(`Unknown model: ${model}`);
178	  }
179	
180	  return provider;
181	}
182	
183	/**
184	 * Get provider for a model (async version with database lookup)
185	 */
186	export async function getProviderForModelAsync(model: string): Promise<ModelProvider> {
187	  const resolvedModel = await resolveModelAliasAsync(model);
188	
189	  // Check database first
190	  const models = await getModelCache();
191	  const cachedModel = models.get(resolvedModel);
192	  if (cachedModel) {
193	    return cachedModel.provider;
194	  }
195	
196	  // Fall back to hardcoded mapping
197	  const provider = MODEL_PROVIDERS[resolvedModel];
198	  if (provider) {
199	    return provider;
200	  }
201	
202	  // Try to infer from model name
203	  if (resolvedModel.startsWith('gpt-') || resolvedModel.startsWith('o1')) {
204	    return 'openai';
205	  }
206	  if (resolvedModel.startsWith('claude')) {
207	    return 'anthropic';
208	  }
209	  if (resolvedModel.startsWith('gemini')) {
210	    return 'google';
211	  }
212	  if (resolvedModel.startsWith('grok')) {
213	    return 'xai';
214	  }
215	  if (resolvedModel.startsWith('deepseek')) {
216	    return 'deepseek';
217	  }
218	
219	  throw new Error(`Unknown model: ${model}`);
220	}
221	
222	/**
223	 * Get API key for provider from environment
224	 */
225	function getApiKey(provider: ModelProvider): string {
226	  const keys: Record<ModelProvider, string | undefined> = {
227	    openai: process.env.OPENAI_API_KEY,
228	    anthropic: process.env.ANTHROPIC_API_KEY,
229	    google: process.env.GOOGLE_API_KEY,
230	    xai: process.env.XAI_API_KEY,
231	    deepseek: process.env.DEEPSEEK_API_KEY,
232	  };
233	
234	  const key = keys[provider];
235	  if (!key) {
236	    throw new Error(`API key not configured for provider: ${provider}`);
237	  }
238	
239	  // DEBUG: Log last 4 chars of key to verify correct key is being used
240	  console.log(`[ModelRouter] Using ${provider} key ending in: ...${key.slice(-4)}`);
241	
242	  return key;
243	}
244	
245	/**
246	 * Sanitize provider error messages to prevent information disclosure.
247	 * SECURITY: Removes sensitive information like API keys from error messages.
248	 */
249	function sanitizeProviderError(
250	  error: { error?: { message?: string; type?: string; code?: string } } | undefined,
251	  provider: string,
252	  status: number
253	): string {
254	  const message = error?.error?.message || '';
255	  const errorType = error?.error?.type || '';
256	  const errorCode = error?.error?.code || '';
257	
258	  // Handle specific HTTP status codes first
259	  if (status === 401) {
260	    return `${provider} authentication error: Invalid or missing API key`;
261	  }
262	
263	  // Check for authentication-related error types/codes
264	  if (
265	    errorType === 'invalid_api_key' ||
266	    errorCode === 'invalid_api_key' ||
267	    errorType === 'authentication_error'
268	  ) {
269	    return `${provider} authentication error: Invalid API key`;
270	  }
271	
272	  // Check for model not found errors
273	  if (
274	    errorCode === 'model_not_found' ||
275	    errorType === 'invalid_request_error' ||
276	    message.toLowerCase().includes('does not exist') ||
277	    message.toLowerCase().includes('model not found') ||
278	    message.toLowerCase().includes('invalid model')
279	  ) {
280	    // Safe to show model-related errors
281	    if (message && message.length < 300) {
282	      return message;
283	    }
284	    return `${provider} error: Model not found or invalid request`;
285	  }
286	
287	  // Patterns that indicate actual sensitive data in the message
288	  const sensitivePatterns = [
289	    /sk-[a-zA-Z0-9]+/,  // OpenAI API key pattern
290	    /AIza[a-zA-Z0-9-_]+/,  // Google API key pattern
291	    /x-goog-api-key/i,
292	    /your api key/i,
293	    /api key.*is/i,
294	  ];
295	
296	  for (const pattern of sensitivePatterns) {
297	    if (pattern.test(message)) {
298	      return `${provider} authentication error`;
299	    }
300	  }
301	
302	  // Return the actual message for other errors (rate limits, etc.)
303	  if (message && message.length < 300) {
304	    return message;
305	  }
306	
307	  return `${provider} API error: ${status}`;
308	}
309	
310	/**
311	 * Convert messages to Anthropic format
312	 */
313	function convertToAnthropicMessages(
314	  messages: ChatMessage[]
315	): { system?: string; messages: Array<{ role: 'user' | 'assistant'; content: string }> } {
316	  let systemPrompt: string | undefined;
317	  const anthropicMessages: Array<{ role: 'user' | 'assistant'; content: string }> = [];
318	
319	  for (const msg of messages) {
320	    if (msg.role === 'system') {
321	      systemPrompt = (systemPrompt || '') + (msg.content || '');
322	    } else if (msg.role === 'user' || msg.role === 'assistant') {
323	      anthropicMessages.push({
324	        role: msg.role,
325	        content: msg.content || '',
326	      });
327	    }
328	  }
329	
330	  return { system: systemPrompt, messages: anthropicMessages };
331	}
332	
333	/**
334	 * Convert messages to Google (Gemini) format
335	 */
336	function convertToGoogleMessages(
337	  messages: ChatMessage[]
338	): { systemInstruction?: { parts: { text: string }[] }; contents: Array<{ role: string; parts: { text: string }[] }> } {
339	  let systemInstruction: { parts: { text: string }[] } | undefined;
340	  const contents: Array<{ role: string; parts: { text: string }[] }> = [];
341	
342	  for (const msg of messages) {
343	    if (msg.role === 'system') {
344	      systemInstruction = { parts: [{ text: msg.content || '' }] };
345	    } else {
346	      contents.push({
347	        role: msg.role === 'assistant' ? 'model' : 'user',
348	        parts: [{ text: msg.content || '' }],
349	      });
350	    }
351	  }
352	
353	  return { systemInstruction, contents };
354	}
355	
356	/**
357	 * Call OpenAI API
358	 */
359	async function callOpenAI(
360	  request: ChatCompletionRequest,
361	  apiKey: string
362	): Promise<ChatCompletionResponse> {
363	  // Build request body, only including optional params if explicitly set
364	  // Some models (like GPT-5) have restrictions on certain parameters
365	  const requestBody: Record<string, unknown> = {
366	    model: resolveModelAlias(request.model),
367	    messages: request.messages,
368	    stream: false,
369	  };
370	
371	  // Only include optional parameters if they're explicitly set
372	  if (request.max_tokens !== undefined) {
373	    requestBody.max_completion_tokens = request.max_tokens;
374	  }
375	  if (request.temperature !== undefined && request.temperature !== 0.7) {
376	    // Only send non-default temperature (some models only support default)
377	    requestBody.temperature = request.temperature;
378	  }
379	  if (request.top_p !== undefined) {
380	    requestBody.top_p = request.top_p;
381	  }
382	  if (request.n !== undefined && request.n !== 1) {
383	    requestBody.n = request.n;
384	  }
385	  if (request.stop !== undefined) {
386	    requestBody.stop = request.stop;
387	  }
388	  if (request.presence_penalty !== undefined && request.presence_penalty !== 0) {
389	    requestBody.presence_penalty = request.presence_penalty;
390	  }
391	  if (request.frequency_penalty !== undefined && request.frequency_penalty !== 0) {
392	    requestBody.frequency_penalty = request.frequency_penalty;
393	  }
394	  if (request.user !== undefined) {
395	    requestBody.user = request.user;
396	  }
397	
398	  const response = await fetch(`${PROVIDER_URLS.openai}/chat/completions`, {
399	    method: 'POST',
400	    headers: {
401	      'Content-Type': 'application/json',
402	      Authorization: `Bearer ${apiKey}`,
403	    },
404	    body: JSON.stringify(requestBody),
405	  });
406	
407	  if (!response.ok) {
408	    const error = await response.json();
409	    throw new Error(sanitizeProviderError(error, 'OpenAI', response.status));
410	  }
411	
412	  return response.json();
413	}
414	
415	/**
416	 * Call OpenAI API with streaming
417	 */
418	async function* callOpenAIStreaming(
419	  request: ChatCompletionRequest,
420	  apiKey: string
421	): AsyncGenerator<ChatCompletionChunk> {
422	  // Build request body, only including optional params if explicitly set
423	  // Some models (like GPT-5) have restrictions on certain parameters
424	  const requestBody: Record<string, unknown> = {
425	    model: resolveModelAlias(request.model),
426	    messages: request.messages,
427	    stream: true,
428	  };
429	
430	  // Only include optional parameters if they're explicitly set
431	  if (request.max_tokens !== undefined) {
432	    requestBody.max_completion_tokens = request.max_tokens;
433	  }
434	  if (request.temperature !== undefined && request.temperature !== 0.7) {
435	    // Only send non-default temperature (some models only support default)
436	    requestBody.temperature = request.temperature;
437	  }
438	  if (request.top_p !== undefined) {
439	    requestBody.top_p = request.top_p;
440	  }
441	  if (request.n !== undefined && request.n !== 1) {
442	    requestBody.n = request.n;
443	  }
444	  if (request.stop !== undefined) {
445	    requestBody.stop = request.stop;
446	  }
447	  if (request.presence_penalty !== undefined && request.presence_penalty !== 0) {
448	    requestBody.presence_penalty = request.presence_penalty;
449	  }
450	  if (request.frequency_penalty !== undefined && request.frequency_penalty !== 0) {
451	    requestBody.frequency_penalty = request.frequency_penalty;
452	  }
453	  if (request.user !== undefined) {
454	    requestBody.user = request.user;
455	  }
456	
457	  const response = await fetch(`${PROVIDER_URLS.openai}/chat/completions`, {
458	    method: 'POST',
459	    headers: {
460	      'Content-Type': 'application/json',
461	      Authorization: `Bearer ${apiKey}`,
462	    },
463	    body: JSON.stringify(requestBody),
464	  });
465	
466	  if (!response.ok) {
467	    const error = await response.json();
468	    throw new Error(sanitizeProviderError(error, 'OpenAI', response.status));
469	  }
470	
471	  const reader = response.body?.getReader();
472	  if (!reader) throw new Error('No response body');
473	
474	  const decoder = new TextDecoder();
475	  let buffer = '';
476	
477	  while (true) {
478	    const { done, value } = await reader.read();
479	    if (done) break;
480	
481	    buffer += decoder.decode(value, { stream: true });
482	    const lines = buffer.split('\n');
483	    buffer = lines.pop() || '';
484	
485	    for (const line of lines) {
486	      const trimmed = line.trim();
487	      if (trimmed.startsWith('data: ')) {
488	        const data = trimmed.slice(6);
489	        if (data === '[DONE]') return;
490	        try {
491	          yield JSON.parse(data) as ChatCompletionChunk;
492	        } catch {
493	          // Skip invalid JSON
494	        }
495	      }
496	    }
497	  }
498	}
499	
500	/**
501	 * Call Anthropic API
502	 */
503	async function callAnthropic(
504	  request: ChatCompletionRequest,
505	  apiKey: string
506	): Promise<ChatCompletionResponse> {
507	  const { system, messages } = convertToAnthropicMessages(request.messages);
508	  const resolvedModel = resolveModelAlias(request.model);
509	
510	  const response = await fetch(`${PROVIDER_URLS.anthropic}/messages`, {
511	    method: 'POST',
512	    headers: {
513	      'Content-Type': 'application/json',
514	      'x-api-key': apiKey,
515	      'anthropic-version': '2023-06-01',
516	    },
517	    body: JSON.stringify({
518	      model: resolvedModel,
519	      system,
520	      messages,
521	      max_tokens: request.max_tokens || 4096,
522	      temperature: request.temperature,
523	      top_p: request.top_p,
524	      stop_sequences: Array.isArray(request.stop) ? request.stop : request.stop ? [request.stop] : undefined,
525	    }),
526	  });
527	
528	  if (!response.ok) {
529	    const error = await response.json();
530	    throw new Error(sanitizeProviderError(error, 'Anthropic', response.status));
531	  }
532	
533	  const anthropicResponse = await response.json();
534	
535	  // Convert Anthropic response to OpenAI format
536	  return {
537	    id: anthropicResponse.id,
538	    object: 'chat.completion',
539	    created: Math.floor(Date.now() / 1000),
540	    model: anthropicResponse.model,
541	    choices: [
542	      {
543	        index: 0,
544	        message: {
545	          role: 'assistant',
546	          content: anthropicResponse.content[0]?.text || '',
547	        },
548	        finish_reason: anthropicResponse.stop_reason === 'end_turn' ? 'stop' : anthropicResponse.stop_reason,
549	      },
550	    ],
551	    usage: {
552	      prompt_tokens: anthropicResponse.usage?.input_tokens || 0,
553	      completion_tokens: anthropicResponse.usage?.output_tokens || 0,
554	      total_tokens: (anthropicResponse.usage?.input_tokens || 0) + (anthropicResponse.usage?.output_tokens || 0),
555	    },
556	  };
557	}
558	
559	/**
560	 * Call Anthropic API with streaming
561	 */
562	async function* callAnthropicStreaming(
563	  request: ChatCompletionRequest,
564	  apiKey: string
565	): AsyncGenerator<ChatCompletionChunk> {
566	  const { system, messages } = convertToAnthropicMessages(request.messages);
567	  const resolvedModel = resolveModelAlias(request.model);
568	
569	  const response = await fetch(`${PROVIDER_URLS.anthropic}/messages`, {
570	    method: 'POST',
571	    headers: {
572	      'Content-Type': 'application/json',
573	      'x-api-key': apiKey,
574	      'anthropic-version': '2023-06-01',
575	    },
576	    body: JSON.stringify({
577	      model: resolvedModel,
578	      system,
579	      messages,
580	      max_tokens: request.max_tokens || 4096,
581	      temperature: request.temperature,
582	      top_p: request.top_p,
583	      stop_sequences: Array.isArray(request.stop) ? request.stop : request.stop ? [request.stop] : undefined,
584	      stream: true,
585	    }),
586	  });
587	
588	  if (!response.ok) {
589	    const error = await response.json();
590	    throw new Error(sanitizeProviderError(error, 'Anthropic', response.status));
591	  }
592	
593	  const reader = response.body?.getReader();
594	  if (!reader) throw new Error('No response body');
595	
596	  const decoder = new TextDecoder();
597	  let buffer = '';
598	  const messageId = `chatcmpl-${Date.now()}`;
599	  const created = Math.floor(Date.now() / 1000);
600	
601	  while (true) {
602	    const { done, value } = await reader.read();
603	    if (done) break;
604	
605	    buffer += decoder.decode(value, { stream: true });
