/**
 * Model Router Types
 *
 * OpenAI-compatible chat completion request/response types
 * for the unified Model Router API.
 */

// Provider types (extended to include xAI and DeepSeek)
export type ModelProvider = 'openai' | 'anthropic' | 'google' | 'xai' | 'deepseek';

// Chat message role
export type ChatMessageRole = 'system' | 'user' | 'assistant' | 'function' | 'tool';

// Chat message structure
export interface ChatMessage {
  role: ChatMessageRole;
  content: string | null;
  name?: string;
  function_call?: {
    name: string;
    arguments: string;
  };
  tool_calls?: Array<{
    id: string;
    type: 'function';
    function: {
      name: string;
      arguments: string;
    };
  }>;
}

// OpenAI-compatible request format
export interface ChatCompletionRequest {
  model: string;
  messages: ChatMessage[];
  temperature?: number;
  top_p?: number;
  n?: number;
  stream?: boolean;
  stop?: string | string[];
  max_tokens?: number;
  presence_penalty?: number;
  frequency_penalty?: number;
  logit_bias?: Record<string, number>;
  user?: string;
  // Additional fields for routing
  provider?: ModelProvider; // Override automatic provider detection
}

// Response choice
export interface ChatCompletionChoice {
  index: number;
  message: ChatMessage;
  finish_reason: 'stop' | 'length' | 'function_call' | 'tool_calls' | 'content_filter' | null;
}

// Streaming choice delta
export interface ChatCompletionChunkChoice {
  index: number;
  delta: Partial<ChatMessage>;
  finish_reason: 'stop' | 'length' | 'function_call' | 'tool_calls' | 'content_filter' | null;
}

// Usage information
export interface ChatCompletionUsage {
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
}

// OpenAI-compatible response format
export interface ChatCompletionResponse {
  id: string;
  object: 'chat.completion';
  created: number;
  model: string;
  choices: ChatCompletionChoice[];
  usage?: ChatCompletionUsage;
  system_fingerprint?: string;
}

// Streaming response chunk
export interface ChatCompletionChunk {
  id: string;
  object: 'chat.completion.chunk';
  created: number;
  model: string;
  choices: ChatCompletionChunkChoice[];
  system_fingerprint?: string;
}

// Model info for routing
export interface ModelInfo {
  id: string;
  provider: ModelProvider;
  displayName: string;
  contextWindow: number;
  maxOutputTokens: number;
  inputPricePerMillion: number;  // USD per 1M tokens
  outputPricePerMillion: number; // USD per 1M tokens
}

// Provider configuration
export interface ProviderConfig {
  apiKey: string;
  baseUrl?: string;
  organizationId?: string;
}

// Error response
export interface ChatCompletionError {
  error: {
    message: string;
    type: string;
    code: string;
    param?: string;
  };
}

// Model alias mapping (user-friendly names to actual model IDs)
export const MODEL_ALIASES: Record<string, string> = {
  // OpenAI aliases
  'gpt-4': 'gpt-4o',
  'gpt-4-turbo': 'gpt-4-turbo-preview',
