33	/**
34	 * withProfileAuth redirects an anonymous caller to /login by throwing a Next
35	 * redirect error. Every action here answers with a { success, error } shape, so
36	 * each catch has to let that one through rather than reporting it as a failure.
37	 */
38	function rethrowIfRedirect(error: unknown): void {
39	  if (isRedirectError(error)) {
40	    throw error;
41	  }
42	}
43	
44	/**
45	 * withProfileAuth signals a foreign profile by throwing, but every action here
46	 * answers with a { success, error } shape and the playground hook reads it. So
47	 * the refusal is converted, while a redirect — how the helper turns away an
48	 * anonymous caller — is let through untouched.
49	 */
50	async function withOwnedProfile<T>(
51	  profileUuid: string,
52	  fn: () => Promise<T>
53	): Promise<T | { success: false; error: string }> {
54	  // Two separate concerns, and both reviews on this were right.
55	  //
56	  // The ownership check runs on its own, so the catch cannot see errors thrown
57	  // by the action body — otherwise an authorized action that threw
