15	  maxTokens: number;
16	  logLevel: 'error' | 'warn' | 'info' | 'debug';
17	  ragEnabled?: boolean;
18	};
19	
20	type PlaygroundSettingsResult =
21	  | { success: true; settings: PlaygroundSettings; error?: undefined }
22	  | { success: false; error: string; settings?: undefined };
23	
24	const playgroundSettingsSchema = z.object({
25	  provider: z.enum(['anthropic', 'openai', 'google'], { message: 'Invalid provider' }),
26	  model: z.string().min(1).max(200),
27	  temperature: z.number().min(0, 'Temperature must be between 0 and 1').max(1, 'Temperature must be between 0 and 1'),
28	  maxTokens: z.number().int().min(100, 'Max tokens must be between 100 and 4000').max(4000, 'Max tokens must be between 100 and 4000'),
29	  logLevel: z.enum(['error', 'warn', 'info', 'debug'], { message: 'Invalid log level' }),
30	  ragEnabled: z.boolean().optional(),
31	});
32	
33	// Both actions are callable from the client with any profileUuid, so every
34	// read and write happens inside withProfileAuth: the session must own the
35	// profile. A redirect (anonymous caller) is let through untouched; any other
36	// failure keeps the { success: false, error } shape the playground hook reads.
37	
38	export async function getPlaygroundSettings(profileUuid: string): Promise<PlaygroundSettingsResult> {
39	  try {
40	    return await withProfileAuth(profileUuid, async (_session, profile): Promise<PlaygroundSettingsResult> => {
41	      const settings = await db.query.playgroundSettingsTable.findFirst({
42	        where: eq(playgroundSettingsTable.profile_uuid, profile.uuid),
43	      });
44	
45	      if (!settings) {
46	        // Return default settings if none exist
47	        return {
48	          success: true,
49	          settings: {
50	            provider: 'anthropic',
51	            model: 'claude-3-7-sonnet-20250219',
52	            temperature: 0,
53	            maxTokens: 1000,
54	            logLevel: 'info',
55	            ragEnabled: false,
56	          } as PlaygroundSettings,
57	        };
58	      }
59	
60	      return {
61	        success: true,
62	        settings: {
63	          provider: settings.provider as 'anthropic' | 'openai' | 'google',
64	          model: settings.model,
65	          temperature: settings.temperature,
66	          maxTokens: settings.max_tokens,
67	          logLevel: settings.log_level as 'error' | 'warn' | 'info' | 'debug',
68	          ragEnabled: settings.rag_enabled || false,
69	        } as PlaygroundSettings,
70	      };
71	    });
72	  } catch (error) {
73	    if (isRedirectError(error)) throw error;
74	    console.error('Failed to get playground settings:', error);
75	    return {
76	      success: false,
77	      error: error instanceof Error ? error.message : 'Failed to get settings',
78	    };
79	  }
80	}
81	
82	export async function updatePlaygroundSettings(
83	  profileUuid: string,
84	  settings: PlaygroundSettings
85	): Promise<PlaygroundSettingsResult> {
86	  try {
87	    return await withProfileAuth(profileUuid, async (_session, profile): Promise<PlaygroundSettingsResult> => {
88	      const parsed = playgroundSettingsSchema.safeParse(settings);
89	      if (!parsed.success) {
90	        throw new Error(parsed.error.issues[0]?.message || 'Invalid settings');
91	      }
92	      const valid = parsed.data;
93	
94	      // Check if settings exist
95	      const existingSettings = await db.query.playgroundSettingsTable.findFirst({
96	        where: eq(playgroundSettingsTable.profile_uuid, profile.uuid),
97	      });
98	
99	      if (existingSettings) {
100	        // Update existing settings
101	        await db
102	          .update(playgroundSettingsTable)
103	          .set({
104	            provider: valid.provider,
105	            model: valid.model,
106	            temperature: valid.temperature,
107	            max_tokens: valid.maxTokens,
108	            log_level: valid.logLevel,
109	            rag_enabled: valid.ragEnabled || false,
110	            updated_at: new Date(),
111	          })
112	          .where(eq(playgroundSettingsTable.profile_uuid, profile.uuid));
113	      } else {
114	        // Create new settings
115	        await db.insert(playgroundSettingsTable).values({
116	          profile_uuid: profile.uuid,
117	          provider: valid.provider,
118	          model: valid.model,
119	          temperature: valid.temperature,
120	          max_tokens: valid.maxTokens,
121	          log_level: valid.logLevel,
122	          rag_enabled: valid.ragEnabled || false,
123	        });
124	      }
125	
126	      return {
127	        success: true,
128	        settings: valid as PlaygroundSettings,
129	      };
130	    });
131	  } catch (error) {
132	    if (isRedirectError(error)) throw error;
133	    return {
134	      success: false,
135	      error: error instanceof Error ? error.message : 'Failed to update settings',
136	    };
137	  }
138	}
