1	#!/usr/bin/env tsx
2	/**
3	 * Rebuilds the zvec `rag` collection from PostgreSQL `document_chunks`.
4	 *
5	 * Re-runnable. For each chunk it generates an embedding from `chunk_text`
6	 * and upserts a vector keyed by `${document_uuid}-${chunk_index}`. Per-document
7	 * vectors are deleted before re-insert so the collection stays in sync with PG
8	 * even if chunk counts changed.
9	 *
10	 * Usage:
11	 *   pnpm reindex:rag
12	 *   pnpm reindex:rag -- --dry
13	 *   pnpm reindex:rag -- --doc=<uuid>
14	 *   pnpm reindex:rag -- --project=<uuid>
15	 *   pnpm reindex:rag -- --batch=8
16	 *
17	 * zvec holds a single-writer RocksDB lock per collection path. The script writes
18	 * to ZVEC_DATA_PATH, which (in production) is a different path than the one the
19	 * running service had on startup — so it can run while the service is up. After
20	 * a service restart picks up the new env, the populated collection becomes live.
21	 *
22	 * Note: this script does not import lib/vectors/vector-service because that
23	 * module uses named ESM imports from `@zvec/zvec` (a CJS package) which fails
24	 * under direct tsx execution. The collection schema is replicated here.
25	 */
26	
27	import { config } from 'dotenv';
28	config();
29	
30	import { existsSync, renameSync, rmSync } from 'fs';
31	import path from 'path';
32	
33	import { and, asc, eq } from 'drizzle-orm';
34	
35	// CJS default import — works under Node ESM regardless of named-export visibility.
36	import zvecPkg from '@zvec/zvec';
37	
38	const {
39	  ZVecCollectionSchema,
40	  ZVecCreateAndOpen,
41	  ZVecDataType,
42	  ZVecIndexType,
43	  ZVecInitialize,
44	  ZVecMetricType,
45	  ZVecOpen,
46	} = zvecPkg as any;
47	
48	// ─── CLI ──────────────────────────────────────────────────────────────────
49	
50	const args = process.argv.slice(2);
51	const isDryRun = args.includes('--dry') || args.includes('--dry-run');
52	const docFilter = args.find((a) => a.startsWith('--doc='))?.split('=')[1];
53	const projectFilter = args.find((a) => a.startsWith('--project='))?.split('=')[1];
54	const batchArg = args.find((a) => a.startsWith('--batch='))?.split('=')[1];
55	const BATCH_SIZE = (() => {
56	  if (!batchArg) return 16;
57	  const parsed = Number.parseInt(batchArg, 10);
58	  if (!Number.isFinite(parsed) || parsed <= 0) {
59	    throw new Error(`invalid --batch value: "${batchArg}" (expected positive integer)`);
60	  }
61	  return parsed;
62	})();
63	
64	const fmt = (n: number) => n.toLocaleString('en-US');
65	
66	// ─── zvec collection management (rag-only, mirrors vector-service.ts) ─────
67	
68	const RAG_DOMAIN = 'rag';
69	const INVERT_INDEX = { indexType: ZVecIndexType.INVERT } as const;
70	
71	function resolveDataDir(): string {
72	  const raw =
73	    process.env.ZVEC_DATA_PATH ||
74	    process.env.MEMORY_VECTOR_DATA_DIR ||
75	    path.join(process.cwd(), 'data', 'vectors');
76	  return path.resolve(raw);
77	}
78	
79	function ragCollectionSchema(dim: number) {
80	  return new ZVecCollectionSchema({
81	    name: RAG_DOMAIN,
82	    vectors: {
83	      name: 'embedding',
84	      dataType: ZVecDataType.VECTOR_FP32,
85	      dimension: dim,
86	      indexParams: {
87	        indexType: ZVecIndexType.HNSW,
88	        metricType: ZVecMetricType.COSINE,
89	      },
90	    },
91	    fields: [
92	      { name: 'project_uuid', dataType: ZVecDataType.STRING, indexParams: INVERT_INDEX },
93	      { name: 'document_uuid', dataType: ZVecDataType.STRING, indexParams: INVERT_INDEX },
94	      { name: 'chunk_uuid', dataType: ZVecDataType.STRING, indexParams: INVERT_INDEX },
95	    ],
96	  });
97	}
98	
99	/**
100	 * Open errors we treat as "no usable collection on disk, safe to (re)create".
101	 * Anything else — permission errors, version mismatches, unexpected internal
102	 * errors — we rethrow rather than silently wipe the directory.
103	 */
104	function isRecreatableOpenError(msg: string): boolean {
105	  return (
106	    msg.includes('No such file or directory') ||
107	    msg.includes('Invalid collection') ||
108	    msg.includes('Invalid manifest') ||
109	    msg.includes('Failed to open') ||
110	    msg.includes('Invalid argument') ||
111	    msg.includes('Invalid checksum') ||
112	    msg.includes('Corruption')
113	  );
114	}
115	
116	function openOrCreateRagCollection(dataDir: string, dim: number) {
117	  ZVecInitialize({ logLevel: 2 });
118	  const collectionPath = path.join(dataDir, RAG_DOMAIN);
119	
120	  try {
121	    return ZVecOpen(collectionPath);
122	  } catch (err: any) {
123	    const msg = err?.message || '';
124	    if (msg.includes('lock hold by') || msg.includes('No locks available')) {
125	      throw new Error(
126	        `zvec lock at ${collectionPath} is held by another process. ` +
